a6=A.at(0,"L1-26",1,A.a([A.f("Golden Cross - a potential bullish signal","Golden Cross (giao c\u1eaft v\xe0ng) - t\xedn hi\u1ec7u t\u0103ng ti\u1ec1m n\u0103ng","\u9ec4\u91d1\u4ea4\u53c9\uff08\u91d1\u53c9\uff09\u2014\u2014\u6f5c\u5728\u770b\u6da8\u4fe1\u53f7","\u30b4\u30fc\u30eb\u30c7\u30f3\u30af\u30ed\u30b9 - \u6f5c\u5728\u7684\u306a\u4e0a\u6607\u30b7\u30b0\u30ca\u30eb","\uace8\ub4e0\ud06c\ub85c\uc2a4 - \uc7a0\uc7ac\uc801 \uc0c1\uc2b9 \uc2e0\ud638"),A.f("Death Cross - a bearish signal","Death Cross - t\xedn hi\u1ec7u gi\u1ea3m","\u6b7b\u4ea1\u4ea4\u53c9\uff08\u6b7b\u53c9\uff09\u2014\u2014\u770b\u8dcc\u4fe1\u53f7","\u30c7\u30c3\u30c9\u30af\u30ed\u30b9 - \u4e0b\u843d\u30b7\u30b0\u30ca\u30eb","\ub370\ub4dc\ud06c\ub85c\uc2a4 - \ud558\ub77d \uc2e0\ud638"),A.f("No specific name","Kh\xf4ng c\xf3 t\xean g\u1ecdi ri\xeang","\u6ca1\u6709\u7279\u5b9a\u540d\u79f0","\u7279\u5225\u306a\u540d\u79f0\u306f\u306a\u3044","\ud2b9\ubcc4\ud55c \uc774\ub984 \uc5c6\uc74c"),A.f("A type of chart error","M\u1ed9t lo\u1ea1i l\u1ed7i bi\u1ec3u \u0111\u1ed3","\u4e00\u79cd\u56fe\u8868\u9519\u8bef","\u30c1\u30e3\u30fc\u30c8\u30a8\u30e9\u30fc\u306e\u4e00\u7a2e","\ucc28\ud2b8 \uc624\ub958\uc758 \ud55c \uc885\ub958")],f8),a7,a6)
